CREATE TABLE notificaciones(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario_id BIGINT NOT NULL,tipo VARCHAR(60) NOT NULL,canal VARCHAR(15) NOT NULL,asunto VARCHAR(180) NOT NULL,mensaje VARCHAR(1200) NOT NULL,estado VARCHAR(15) NOT NULL,leida BOOLEAN NOT NULL DEFAULT FALSE,fecha_creacion TIMESTAMP NOT NULL,fecha_envio TIMESTAMP,detalle_envio VARCHAR(300));CREATE INDEX idx_notificacion_usuario ON notificaciones(usuario_id,leida);